#!/usr/bin/env bash
# Restore the icon theme that was active before this template was enabled.
# Does nothing when there is nothing recorded to restore.
# This section has been AI-generated by Gemini 3.8 Flash (High) on 21.11.2026
set -euo pipefail

CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
STATE="$CONFIG_HOME/noctalia/slot-beauty-icons.state"
CONFIG_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
DATA_HOME="${XDG_DATA_HOME:-$HOME/.local/share}"
DEST="$DATA_HOME/icons/Slot-Beauty-Dark-Icons-V-2-Noctalia"

# shellcheck source=pins.sh
source "$CONFIG_DIR/pins.sh"

[[ -f "$STATE" ]] || exit 0

ini_set() { # file group key value
  local file="$1" group="$2" key="$3" value="$4"
  [[ -f "$file" ]] || return 0
  if grep -qE "^[[:space:]]*${key}[[:space:]]*=" "$file"; then
    if [[ -z "$value" ]]; then
      # The key was not set before the template ran: remove it again.
      sed -i -E "/^[[:space:]]*${key}[[:space:]]*=/d" "$file"
    elif ! grep -qxF "${key}=${value}" "$file"; then
      sed -i -E "s|^[[:space:]]*${key}[[:space:]]*=.*|${key}=${value}|" "$file"
    fi
  elif [[ -n "$value" ]]; then
    if grep -qxF "[${group}]" "$file"; then
      sed -i -E "0,/^\[${group}\]\$/s//[${group}]\n${key}=${value}/" "$file"
    else
      printf '\n[%s]\n%s=%s\n' "$group" "$key" "$value" >> "$file"
    fi
  fi
}

declare -A remembered=()
while IFS='=' read -r key value; do
  remembered["$key"]="$value"
done < "$STATE"

for key in "${!remembered[@]}"; do
  value="${remembered[$key]}"
  case "$key" in
    gsettings)
      if command -v gsettings >/dev/null 2>&1 && [[ -n "$value" ]]; then
        val_clean="${value//\'/}"
        gsettings set org.gnome.desktop.interface icon-theme "'$val_clean'" 2>/dev/null || true
      fi
      ;;
    gtk3)
      ini_set "$CONFIG_HOME/gtk-3.0/settings.ini" Settings gtk-icon-theme-name "$value"
      ;;
    gtk4)
      ini_set "$CONFIG_HOME/gtk-4.0/settings.ini" Settings gtk-icon-theme-name "$value"
      ;;
    qt5)
      ini_set "$CONFIG_HOME/qt5ct/qt5ct.conf" Appearance icon_theme "$value"
      ;;
    qt6)
      ini_set "$CONFIG_HOME/qt6ct/qt6ct.conf" Appearance icon_theme "$value"
      ;;
  esac
done

# The pins outside GTK/Qt/GSettings go back to the value they held before.
restore_pins() {
  local key file read_re write_re value
  while IFS='|' read -r key file read_re write_re; do
    [[ -n "$key" ]] || continue
    value="${remembered[$key]:-}"
    [[ -n "$value" ]] || continue
    pin_write "$file" "$write_re" "$value"
  done < <(pin_rows)
}

restore_pins

rm -f "$STATE"

# Notify file watchers
touch "$DEST" "$DATA_HOME/icons" 2>/dev/null || true
exit 0
